const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Qty = () => {
  const [count, setCount] = useState(1);

  console.log('그려집니다. 이번 렌더의 count =', count);

  const up = () => {
    setCount(count + 1);
  };

  return (
    <article className="card">
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <div className="qty">
        <button className="qty__up" type="button" onClick={up}>+1</button>
        <span className="qty__value">{count}개</span>
      </div>
    </article>
  );
};

root.render(<Qty />);

