const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Qty = () => {
  const [count, setCount] = useState(1);

  return (
    <article className="card">
      <h3 className="card__title">오버사이즈 셔츠</h3>
      <div className="qty">
        <button className="qty__down" type="button" onClick={() => setCount(count > 1 ? count - 1 : 1)}>−</button>
        <span className="qty__value">{count}개</span>
        <button className="qty__up" type="button" onClick={() => setCount(count + 1)}>+1</button>
        <button className="qty__up2" type="button" onClick={() => setCount(count + 2)}>+2</button>
      </div>
    </article>
  );
};

root.render(<Qty />);
